(async()=>{
    const b64="";
    const bin=atob(b64);const arr=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);
    const fd=new FormData();
    fd.append('file',new Blob([arr],{type:'application/javascript'}),'aerosuite-showcase-zoom.js');
    fd.append('title','aerosuite-showcase-zoom.js');
    const m=await wp.apiFetch({path:'/wp/v2/media',method:'POST',body:fd});
    window.__asDeploy=window.__asDeploy||{};
    window.__asDeploy['zoom']=m.source_url;
    return {key:'zoom',url:m.source_url};
  })()
